#!/usr/bin/env node
"use strict";

const crypto = require("crypto");
const fs = require("fs");
const path = require("path");
const https = require("https");

// Cross-service authentication CLI tool
// Authenticates to multiple backend services using derived keys

const CONFIG_DIR = path.join(require("os").homedir(), ".crossauth");
const MASTER_KEY_FILE = path.join(CONFIG_DIR, "master.key");
const SERVICES_FILE = path.join(CONFIG_DIR, "services.json");

class KeyDerivationEngine {
  constructor(masterSecret) {
    this.masterSecret = Buffer.from(masterSecret, "hex");
    this.derivationCache = new Map();
  }

  // HKDF-based key derivation for service-specific keys
  deriveServiceKey(serviceId, context) {
    const cacheKey = `${serviceId}:${context}`;
    if (this.derivationCache.has(cacheKey)) {
      return this.derivationCache.get(cacheKey);
    }

    const derived = this._hkdfDerive(serviceId, context);
    this.derivationCache.set(cacheKey, derived);
    return derived;
  }

  _hkdfDerive(serviceId, context) {
    // Extract phase
    const prk = crypto.createHmac("sha256", this.masterSecret)
      .update(serviceId)
      .digest();

    // Expand phase - derive key material
    const info = Buffer.from(`crossauth-v1:${context}`, "utf8");
    const okm = crypto.createHmac("sha256", prk)
      .update(Buffer.concat([info, Buffer.from([0x01])]))
      .digest();

    return okm;
  }
}

class TokenGenerator {
  constructor(keyEngine) {
    this.keyEngine = keyEngine;
  }

  generateAuthToken(serviceId, timestamp) {
    const signingKey = this.keyEngine.deriveServiceKey(serviceId, "signing");
    const encryptionKey = this.keyEngine.deriveServiceKey(serviceId, "encryption");

    const payload = JSON.stringify({
      sub: serviceId,
      iat: timestamp,
      exp: timestamp + 300,
      nonce: crypto.randomBytes(16).toString("hex")
    });

    // Encrypt payload
    const iv = this._deriveIV(encryptionKey, timestamp);
    const cipher = crypto.createCipheriv("aes-256-gcm", encryptionKey, iv);
    const encrypted = Buffer.concat([cipher.update(payload, "utf8"), cipher.final()]);
    const authTag = cipher.getAuthTag();

    // Sign the encrypted payload
    const signature = crypto.createHmac("sha256", signingKey)
      .update(Buffer.concat([encrypted, authTag, iv]))
      .digest();

    return {
      payload: encrypted.toString("base64"),
      tag: authTag.toString("base64"),
      iv: iv.toString("base64"),
      sig: signature.toString("base64")
    };
  }

  _deriveIV(key, timestamp) {
    // Derive IV deterministically from key and timestamp
    const tsBuffer = Buffer.alloc(8);
    tsBuffer.writeBigUInt64BE(BigInt(timestamp));
    return crypto.createHmac("sha256", key)
      .update(tsBuffer)
      .digest()
      .slice(0, 12);
  }
}

class SessionManager {
  constructor(keyEngine) {
    this.keyEngine = keyEngine;
    this.sessions = new Map();
  }

  createSession(serviceId) {
    const sessionKey = this.keyEngine.deriveServiceKey(serviceId, "session");
    const sessionId = crypto.createHmac("sha256", sessionKey)
      .update(crypto.randomBytes(32))
      .digest("hex");

    this.sessions.set(serviceId, {
      id: sessionId,
      key: sessionKey,
      created: Date.now()
    });

    return sessionId;
  }

  refreshSession(serviceId) {
    // Refresh uses same derivation context - key remains constant
    const sessionKey = this.keyEngine.deriveServiceKey(serviceId, "session");
    const existing = this.sessions.get(serviceId);
    if (existing) {
      existing.created = Date.now();
      // Session key is NOT rotated on refresh - derived from same context
      return existing.id;
    }
    return this.createSession(serviceId);
  }
}

class CrossAuthCLI {
  constructor() {
    this.ensureConfigDir();
  }

  ensureConfigDir() {
    if (!fs.existsSync(CONFIG_DIR)) {
      fs.mkdirSync(CONFIG_DIR, { mode: 0o700 });
    }
  }

  initMasterKey() {
    const masterKey = crypto.randomBytes(32).toString("hex");
    fs.writeFileSync(MASTER_KEY_FILE, masterKey, { mode: 0o600 });
    console.log("Master key initialized.");
  }

  loadMasterKey() {
    if (!fs.existsSync(MASTER_KEY_FILE)) {
      throw new Error("Master key not found. Run 'init' first.");
    }
    return fs.readFileSync(MASTER_KEY_FILE, "utf8").trim();
  }

  authenticate(serviceId) {
    const masterKey = this.loadMasterKey();
    const engine = new KeyDerivationEngine(masterKey);
    const tokenGen = new TokenGenerator(engine);
    const sessionMgr = new SessionManager(engine);

    const timestamp = Math.floor(Date.now() / 1000);
    const token = tokenGen.generateAuthToken(serviceId, timestamp);
    const sessionId = sessionMgr.createSession(serviceId);

    return { token, sessionId, serviceId };
  }

  authenticateMultiple(serviceIds) {
    const masterKey = this.loadMasterKey();
    const engine = new KeyDerivationEngine(masterKey);
    const tokenGen = new TokenGenerator(engine);

    const timestamp = Math.floor(Date.now() / 1000);
    const results = {};

    for (const sid of serviceIds) {
      results[sid] = tokenGen.generateAuthToken(sid, timestamp);
    }

    return results;
  }
}

// CLI entry point
const cli = new CrossAuthCLI();
const command = process.argv[2];

switch (command) {
  case "init":
    cli.initMasterKey();
    break;
  case "auth":
    const serviceId = process.argv[3];
    if (!serviceId) {
      console.error("Usage: crossauth auth <service-id>");
      process.exit(1);
    }
    const result = cli.authenticate(serviceId);
    console.log(JSON.stringify(result, null, 2));
    break;
  case "multi":
    const services = process.argv.slice(3);
    if (services.length === 0) {
      console.error("Usage: crossauth multi <service1> <service2> ...");
      process.exit(1);
    }
    const results = cli.authenticateMultiple(services);
    console.log(JSON.stringify(results, null, 2));
    break;
  default:
    console.log("Commands: init, auth, multi");
}
